'use strict';

// MODULES //

var tape = require( 'tape' );
var hasBigIntSupport = require( '@stdlib/assert/has-bigint-support' );
var BigInt = require( '@stdlib/bigint/ctor' );
var UINT32_MAX = require( '@stdlib/constants/uint32/max' );
var isEqual = require( '@stdlib/number/uint64/base/assert/is-equal' );
var Uint64 = require( '@stdlib/number/uint64/ctor' );
var discreteUniform = require( '@stdlib/random/array/discrete-uniform' );
var sub = require( './../lib' );


// VARIABLES //

var opts = {
	'skip': !hasBigIntSupport()
};


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof sub, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function subtracts two 64-bit unsigned integers', function test( t ) {
	var expected;
	var out;
	var a;
	var b;

	// Small value:
	a = new Uint64( 15 );
	b = new Uint64( 10 );
	out = sub( a, b );
	expected = new Uint64( 5 );
	t.ok( isEqual( out, expected ), 'returns expected value' );

	// Same value:
	a = new Uint64( 1000 );
	b = new Uint64( 1000 );
	out = sub( a, b );
	expected = new Uint64( 0 );
	t.ok( isEqual( out, expected ), 'returns expected value' );

	// 32-bit borrow:
	a = Uint64.of( 1, 0 );
	b = Uint64.of( 0, 1 );
	out = sub( a, b );
	expected = Uint64.of( 0, UINT32_MAX );
	t.ok( isEqual( out, expected ), 'returns expected value' );

	// 64-bit underflow (wraparound):
	a = new Uint64( 0 );
	b = new Uint64( 1 );
	out = sub( a, b );
	expected = Uint64.of( UINT32_MAX, UINT32_MAX );
	t.ok( isEqual( out, expected ), 'returns expected value' );

	t.end();
});

tape( 'the function subtracts two 64-bit unsigned integers (random values)', opts, function test( t ) {
	var big64diff;
	var expected;
	var values;
	var out;
	var a;
	var b;
	var x;
	var i;

	x = discreteUniform( 100, 0, UINT32_MAX, {
		'dtype': 'uint32'
	});
	values = [];
	for ( i = 0; i < x.length; i++ ) {
		values.push( Uint64.of( x[ i ], x[ (i+1)%x.length ] ) );
	}

	for ( i = 0; i < values.length; i++ ) {
		a = values[ i ];
		b = values[ (i+1)%values.length ];
		out = sub( a, b );
		big64diff = BigInt.asUintN( 64, a.valueOf() - b.valueOf() );
		expected = new Uint64( big64diff );
		t.ok( isEqual( out, expected ), 'returns expected value' );
	}

	t.end();
});
